"""Prepare one-source-per-tile requests after the quiet snow master inspection."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3]
jobs=[]
base=json.loads((HERE/'master-jobs.json').read_text())[0]['args']['prompt'].split('\nONE seamless winter')[0]
def add(name,details,refs,transparent=False):
    prompt=base+'\nWinter version of the attached tile: '+details+'\nExact square1254x1254source canvas represents16x16logical pixels. Flat pixel clusters, no gradients, blur, glitter, glare, footprints, ice, centrepiece, scene objects, labels or ground shadow. Soft warm snow uses bone(#e8e0cf), coolmoon(#cfd6ff), beige bone_dark. Preserve texture density, cluster size, framing and seamless borders of the edit target. Image1 is the exact edit target, further images are style/reference ONLY.\n'
    args={'prompt':prompt,'referenced_image_paths':[str(p) for p in refs],'transparent_background':transparent}
    j={'folder':HERE.name,'stem':name+'-r1','revision':1,'args':args};jobs.append(j)
    (HERE/f'raw/{name}-r1.request.json').write_text(json.dumps(args,indent=2)+'\n',encoding='utf-8');(HERE/f'raw/{name}-r1.prompt.txt').write_text(prompt,encoding='utf-8')
master=HERE/'raw/grass_winter-r1.png'
for name,extra in [('grass_b_winter','One DIFFERENT soft joined pale-blue interior drift of6-14logicalpixels, different placement from the master.'),('grass_c_winter','One soft joined interior drift and ONE tiny joined dark-green grass tuft of3-6logicalpixels.'),('grass_d_winter','One soft interior drift and ONE joined dry stalk cluster of3-6logicalpixels, darker green/ochre but no soil or gold ramp.')]:
    add(name,'An edit of the accepted snow master. Change ONLY the interior cluster. Keep all FOUR border rows/columns pixel-identical and same1254square resolution. At least232of256nativepixels remain solid bone base; all nonbase clusters have at least2connectedpixels. '+extra,[master])
add('path_winter','Trodden packed-snow PATH. Entire tile opaque; dominant base bone_dark(#c9bca3), at least220of256logicalpixels. A few low-contrast joined slushy soil clusters confined to the interior. All four borders uniform base, opposite borders identical. Clearly darker than the bone snow field, no footprints.',[ROOT/'assets/art_source/terrain/path.png',master])
add('soil_winter','Bed SOIL with light dusting of snow. Entire tile opaque; dominant base soil(#6a4a34) on at least200of256logicalpixels, at most40snowpixels in joined cream clusters. All four borders uniform soil and opposite borders identical. NO green or blue; no isolated single pixels.',[ROOT/'assets/art_source/terrain/soil.png',master])
add('tilled_winter','TILLED SOIL with FOUR horizontal furrows, fixed native16grid. Snow ridges on rows0-1,4-5,8-9,12-13, grooves on2-3,6-7,10-11,14-15 stay dark soil. Opposite borders pixel-identical: for vertical wrapping the topmost row0 and bottommostrow15 are BOTH soil-dark; first snow ridge is row1 only, permitted1row ridge tolerance. Rows4-5,8-9,12-13 are broad warm cream; remaining grooves muted warmsoil. No vertical ridge, perspective or objects. Opaque whole tile.',[ROOT/'assets/art_source/crops/tilled.png',master])
add('edge_n_winter','NORTH snow EDGE OVERLAY, never a ground tile. Logical16square canvas. Row0: a COMPLETE joined cream snow line fromx0tox15. A few soft connected scallops extend down ONLYto row1or2 inside x1..14. Columns0and15 opaque ONLYonrow0 and are identical. Every other pixel, especially rows3..15, has alpha ZERO. One4connected snowpiece attachedto0,0. Entire image transparent outside the narrow TOPband; no scene/background/shadow.',[ROOT/'assets/art_source/terrain/edge-n.png',master],True)
add('shore_n_winter','NORTH pond-bank OVERLAY, logical16square canvas. Row0: complete cream snow line x0..15. Row1: narrow warmwood earth bank with snowclumps, connected to row0. At mostONEconnected darkbluewater contact cluster onrow2, confined to x1..14. Columns0and15 EXACTly identical, rows3..15 alphaZERO. One4connected piece including0,0. No water field, complete ground tile, background or shadow: real transparent alpha outside the TOP3rows.',[ROOT/'assets/art_source/terrain/shore-n.png',master],True)
(HERE/'remaining-jobs.json').write_text(json.dumps(jobs,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'planned':len(jobs)}))
